import { useLiveQuery } from 'dexie-react-hooks'
import { db, logAudit, newEnvelope, readable } from '@/db/db'
import type { DataClass, Envelope, Owned } from '@/types/domain'
import type { ContributionModel, Disclosure, MoneySpace, ProposalTier } from './money'
import type { MoneyRights } from './model'

/**
 * Persistence for the Finance module.
 *
 * Five real stores (db.ts v4) rather than one union: an account, a ledger line
 * and a proposal are read on different screens at different rates and share no
 * index. Everything else is the house pattern — `newEnvelope()` on write,
 * `readable()`/`canRead()` on read, and membership of `OWNED_STORES`, so money
 * rows are in an export and are revoked at uncoupling.
 */

export const FINANCE_STORES = [
  'accounts',
  'ledger',
  'splits',
  'contributionRules',
  'proposals',
] as const
export type FinanceStore = (typeof FINANCE_STORES)[number]

// ---------------------------------------------------------------------------
// Records
// ---------------------------------------------------------------------------

/**
 * Every money object answers the same four questions. Three of them are fields
 * here; ownership is the envelope's `ownerProfileId`, which is the one thing a
 * feature is never allowed to invent for itself.
 */
export type FinanceAccount = Owned<
  MoneyRights & {
    kind: 'account'
    name: string
    /** uang saya / uang bersama / uang yang dibagikan */
    space: MoneySpace
    balance: number
    /** Day of month the salary lands. Drives safe-to-spend's window. */
    paydayDom: number
  }
>

/**
 * A transaction, or — when `planned` is true — a bill.
 *
 * The three rights are optional here and only optional here: a row that does not
 * carry them inherits the account's, which is what `resolveRights()` is for.
 * Setting them on the row is how "tagihan di rekening dia, tapi aku yang bayar"
 * gets recorded without moving the money or widening what anyone can see.
 *
 * ponytail: optional fields on an existing store, so no `.version(n)` block is
 * needed — none of them is indexed and old rows resolve through their account.
 * Promote them to required with a backfill only if a query ever needs an index.
 */
export type LedgerEntry = Owned<Partial<MoneyRights> & {
  kind: 'ledger'
  accountId: string
  label: string
  /** Negative is money out, positive is money in. One sign convention, one bug class. */
  amount: number
  category: string
  date: string
  /** Not yet spent: a bill or a commitment that safe-to-spend must reserve. */
  planned: boolean
  /** Planned items may be undated — that uncertainty becomes the estimate's range. */
  dueDate?: string
}>

export type SplitRecord = Owned<Partial<MoneyRights> & {
  kind: 'split'
  label: string
  amount: number
  category: string
  date: string
  paidByProfileId: string
  /** Frozen at write time from the rule in force — history never re-splits itself. */
  model: ContributionModel
  shares: Record<string, number>
  settledAt?: string
}>

export type ContributionRule = Owned<{
  kind: 'rule'
  model: ContributionModel
  /** Effective-dated. A change is a new record; the old one keeps explaining the past. */
  effectiveFrom: string
  incomes?: Record<string, number>
  /** sesuai_kebutuhan — each person's own monthly essentials. */
  needs?: Record<string, number>
  fixed?: Record<string, number>
  byCategory?: Record<string, string>
  rotation?: string[]
  payerProfileId?: string
  shares?: Record<string, number>
  /** Purchase thresholds are part of the agreement, so they are dated with it. */
  notifyAbove: number
  agreeAbove: number
  note?: string
}>

export type PurchaseProposal = Owned<{
  kind: 'proposal'
  label: string
  amount: number
  category: string
  /** Frozen from the thresholds in force on the day it was raised. */
  tier: ProposalTier
  status: 'sent' | 'agreed' | 'declined' | 'noted'
  note?: string
  decidedAt?: string
  decidedByProfileId?: string
}>

export interface FinanceRow {
  accounts: FinanceAccount
  ledger: LedgerEntry
  splits: SplitRecord
  contributionRules: ContributionRule
  proposals: PurchaseProposal
}

// ---------------------------------------------------------------------------
// Read / write
// ---------------------------------------------------------------------------

/** Live read through the same gate as every other store. */
export function useFinance<S extends FinanceStore>(
  store: S,
  viewerProfileId: string | undefined,
  sort?: (a: FinanceRow[S], b: FinanceRow[S]) => number,
): FinanceRow[S][] | undefined {
  return useLiveQuery(async () => {
    if (!viewerProfileId) return []
    const list = await readable<FinanceRow[S]>(store, viewerProfileId)
    return sort ? list.sort(sort) : list
  }, [store, viewerProfileId])
}

export async function addFinance<S extends FinanceStore>(
  store: S,
  ownerProfileId: string,
  dataClass: DataClass,
  body: Omit<FinanceRow[S], keyof Envelope>,
  overrides: Partial<Envelope> = {},
): Promise<string> {
  const env = newEnvelope(ownerProfileId, dataClass, overrides)
  await db.table(store).put({ ...env, ...body })
  await logAudit({
    actorProfileId: ownerProfileId,
    action: 'create',
    objectStore: store,
    objectId: env.id,
    summary: `${store} dibuat`,
  })
  return env.id
}

export async function patchFinance<S extends FinanceStore>(
  store: S,
  id: string,
  changes: Partial<FinanceRow[S]>,
): Promise<void> {
  const current = (await db.table(store).get(id)) as FinanceRow[S] | undefined
  if (!current) return
  await db.table(store).put({
    ...current,
    ...changes,
    updatedAt: new Date().toISOString(),
    version: current.version + 1,
  })
}

/** Soft delete, same as `softDelete()` — permanent erase stays a settings-only flow. */
export async function removeFinance(
  store: FinanceStore,
  id: string,
  actorProfileId: string,
): Promise<void> {
  await patchFinance(store, id, { deletedAt: new Date().toISOString() } as never)
  await logAudit({
    actorProfileId,
    action: 'delete',
    objectStore: store,
    objectId: id,
    summary: 'soft delete',
  })
}

/**
 * Widening who can see an account. Mirrors `db.ts#setVisibility`: only the owner
 * may change it, and a non-owner gets an error rather than a silent no-op.
 */
export async function setAccountDisclosure(
  id: string,
  actorProfileId: string,
  disclosure: Disclosure,
): Promise<void> {
  const account = (await db.accounts.get(id)) as FinanceAccount | undefined
  if (!account) throw new Error(`Tidak ada data accounts/${id}`)
  if (account.ownerProfileId !== actorProfileId) {
    throw new Error('Hanya pemilik data yang bisa mengubah siapa yang boleh lihat.')
  }
  // The envelope stays the source of truth for "can the partner read this row at
  // all"; `disclosure` only decides how much of the body the screen renders.
  await patchFinance('accounts', id, {
    disclosure,
    visibility: disclosure === 'privat' ? 'private' : 'shared',
    ...(disclosure === 'privat'
      ? { revokedAt: new Date().toISOString() }
      : { revokedAt: undefined }),
  } as Partial<FinanceAccount>)
  await logAudit({
    actorProfileId,
    action: disclosure === 'privat' ? 'revoke' : 'share',
    objectStore: 'accounts',
    objectId: id,
    summary: `disclosure → ${disclosure}`,
  })
}
